from pathlib import Path
from xml.sax.saxutils import escape
import textwrap
R=Path(__file__).resolve().parents[2]/'documentation/diagrams';R.mkdir(exist_ok=True)
def start(w,h):return [f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}"><defs><marker id="a" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 Z" fill="#385365"/></marker></defs><rect width="100%" height="100%" fill="white"/>']
def text(s,x,y,t,size=16,anchor='start',color='#172D3E'):
    s.append(f'<text x="{x}" y="{y}" text-anchor="{anchor}" font-family="Arial,sans-serif" font-size="{size}" fill="{color}">{escape(t)}</text>')
def box(s,x,y,w,h,name,lines,fs=14):
    s.append(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="5" fill="#F6F8FA" stroke="#91A8B5"/><path d="M{x+5} {y} H{x+w-5} Q{x+w} {y} {x+w} {y+5} V{y+33} H{x} V{y+5} Q{x} {y} {x+5} {y}" fill="#1C3B50"/>')
    text(s,x+12,y+23,name,20 if fs==18 else 16,color='white')
    for i,l in enumerate(lines):text(s,x+12,y+56+i*21,l,fs)
def line(s,x1,y1,x2,y2,label='',lx=None,ly=None,dash=False):
    s.append(f'<path d="M{x1} {y1} L{x2} {y2}" fill="none" stroke="#385365" stroke-width="2" marker-end="url(#a)"'+(' stroke-dasharray="6 4"'if dash else '')+'/>')
    if label:text(s,lx if lx is not None else (x1+x2)/2,ly if ly is not None else (y1+y2)/2-8,label,13,'middle')
def save(s,n):s.append('</svg>');(R/(n+'.svg')).write_text(''.join(s))
s=start(960,555)
box(s,20,35,270,125,'Public static pages',['Ten Web-to-Lead forms','Shared config and form engine','Org-specific field IDs'])
box(s,345,35,270,125,'Salesforce intake',['Lead submissions','Four after-save Flows','Native conversion'])
box(s,670,35,270,125,'Relationship and booking',['Account and Contact reused','One event Opportunity','One Primary Contact Role'])
line(s,290,96,345,96,'POST',318,81)
line(s,615,96,670,96,'Convert',642,81)
box(s,20,315,270,140,'NTE Management app',['Master Panel and Home','Native records and reports','Relationship and retry LWCs','Operates through Apex APIs'])
box(s,345,315,270,140,'Apex services and audit',['Pricing and supplementary data','Approval and email dispatch','Payment request snapshots','After-commit queue workers'])
box(s,670,315,270,140,'External delivery',['Salesforce outbound email','Stripe fixed Payment Links','Manual payment confirmation','External logo and pack URLs'])
line(s,290,375,345,375,'Apex',318,360)
line(s,615,375,670,375,'API',643,359)
line(s,480,160,480,315,'Flow invokes service',565,240)
line(s,805,160,550,315,'Saved booking facts',774,236)
text(s,20,505,'Outside the integration: general attendee ticketing, quote/invoice creation, refunds and binary logo storage.',16)
text(s,20,535,'Custom metadata holds destinations and merchant selection; protected external credentials hold the API key.',15)
save(s,'system')
