box(s,20,225,250,115,'Organisation  Account',['Latest NTE classification','Standard organisation identity'])
box(s,345,225,270,115,'Event booking  Opportunity',['Record type NTE_Event_Opportunity','Initial price and separate top-up','Finance and preparation history'])
box(s,690,225,250,115,'NTE_Payment_Request__c',['Booking snapshot and Stripe IDs','Opportunity__c lookup','Charge_Key__c unique external ID'])
box(s,20,445,250,105,'Person  Contact',['Latest NTE classification','Primary recipient email'])
box(s,345,445,270,105,'OpportunityContactRole',['OpportunityId and ContactId','IsPrimary and Role','Exactly one Primary required'])
box(s,690,445,250,105,'NTE_Email_Dispatch__c',['Lead__c or Opportunity__c','Recipient and content snapshot','Dispatch_Key__c unique ID'])
line(s,480,120,480,225,'Convert / copy',555,182,True)
line(s,270,280,345,280,'0..1 : 0..*',307,264)
line(s,615,280,690,280,'0..1 : 0..*',652,264)
line(s,270,492,345,492,'1 : 0..*',306,476)
line(s,480,445,480,340,'0..* : 1',540,398)
line(s,615,326,745,445,'0..1 : 0..*',726,385)
s.append('<path d="M615 70 H960 V424 H817 V445" fill="none" stroke="#385365" stroke-width="2" marker-end="url(#a)"/>')
text(s,765,62,'Lead lookup  0..1 : 0..*',14,'middle')
line(s,145,340,145,445,'0..1 : 0..*',215,398)
s.append('<path d="M145 550 V588 H817 V550" fill="none" stroke="#385365" stroke-width="2" marker-end="url(#a)"/>')
text(s,480,578,'Dispatch Contact__c lookup  0..1 : 0..*',14,'middle')
text(s,20,620,'Lookup deletion is SetNull for custom audit relationships. Dotted line denotes conversion, not a lookup.',15)
text(s,20,644,'Default routing and Stripe configuration are custom metadata records; runtime resolves them by name.',15)
save(s,'data')
s=start(960,825)
steps=[('Review application',['Operator chooses Account and Contact, then creates a new event Opportunity.']),('Native conversion supplies related identities',['Salesforce supplies ConvertedAccountId, ConvertedContactId and ConvertedOpportunityId.']),('Reprice and copy in the conversion transaction',['NTEPricingService returns current pricedLead; Flow assigns exact booking fields and Amount.']),('Save pending approval and participant classification',['Flow queues explicit Lead and Opportunity IDs; Account/Contact get latest NTE summaries.']),('After commit prepare the optional Stripe request',['For selected paid Stripe bookings, create/reuse and verify the saved fixed charge/link.']),('Render to the exact Primary Contact and send',['Validate saved price and preparation links; choose exhibitor, partner or complimentary copy.']),('Persist the individual email outcome',['Opportunity approval audit plus Task; accepted Stripe email stamps quote/invoice, never payment.'])]
for i,(name,lines) in enumerate(steps):
    y=20+i*110;box(s,45,y,870,92,str(i+1)+'  '+name,[t for l in lines for t in textwrap.wrap(l,90)],fs=18)
    if i<6:line(s,480,y+92,480,y+110)
text(s,45,810,'First manually recorded base payment later queues one distinct booking-confirmation dispatch.',16)
save(s,'conversion')
s=start(960,825)
steps=[('Create supplementary Lead',['Staff, heavy-vehicle or logo form posts its target booking reference.']),('Reset submitted success fields and queue exact IDs',['Creation Flow invokes applyUpdates; NTEUpdateSubmissionJob runs after commit.']),('Reload in creation and ID order and match reference',['Require one eligible NTE booking; source event code does not retarget the reference.']),('Validate and merge accepted fields per booking',['Check audience, declarations, roster counts, immutable top-up and complete vehicle groups.']),('Save booking changes and applied identity together',['Savepoint protects the Opportunity update plus the Lead applied-booking audit.']),('Attempt staff or heavy-vehicle receipt separately',['Use the matched booking Primary Contact; receipt failure preserves already saved data.']),('Keep or delete the source submission as appropriate',['Delete eligible temporary staff/vehicle Leads only after accepted receipt; retain logo/error records.'])]
for i,(name,lines) in enumerate(steps):
    y=20+i*110;box(s,45,y,870,92,str(i+1)+'  '+name,[t for l in lines for t in textwrap.wrap(l,90)],fs=18)
    if i<6:line(s,480,y+92,480,y+110)
text(s,45,810,'Invalid or ambiguous requests remain auditable Leads. A receipt retry never reapplies booking changes.',16)
save(s,'updates')
print('Created four diagram SVG sources')
